from fastapi_pagination import Page
from fastapi_pagination.customization import (
    CustomizedPage,
    UseName,
    UseParamsFields,
)
from pydantic import Field

MAX_PAGINATION_SIZE = 10000

CustomPage = CustomizedPage[
    Page,
    UseName("Page"),
    UseParamsFields(
        # Field preserves validation metadata without embedding Query defaults
        # in the Annotated dependencies generated by fastapi-pagination.
        page=Field(1, ge=1, description="Page number"),
        size=Field(25, ge=1, le=MAX_PAGINATION_SIZE),
    ),
]
